def register_input_interface(self, input_interface: InputInterface) -> Result[None, str]:
    input_trace_manager = InputTraceManager(input_interface, self._mapping)
    synt_after_input = self._mapping.frp_syntax_after_input()
    ret = self._exec_controller.register_callback_on_break(
        synt_after_input,
        lambda: input_trace_manager.callback_on_stop(self._c_debuggee)
    )
    self._input_trace_manager = input_trace_manager
    self.load_input_cache(timeout_ms=100, max_load_cnt=1000)
    if isinstance(ret, Failure):
        return Failure(ret.failure())
    return Success(None)

def load_input_interface(self) -> Result[None, str]:
    trace = self._saved_iter.load_saved_trace(str(self._mapping.c_entry_file))
    if isinstance(trace, Failure):
        return Failure(trace.failure())
    return self.register_input_interface(self._saved_iter)

def save_input_iter(self):
    if self._input_trace_manager is not None:
        self._input_trace_manager.save_trace(str(self._mapping.c_entry_file))

def input_interface_active(self) -> bool:
    if self._input_trace_manager is not None:
        return True
    return False

import os
import time
from typing import Dict, List, Optional, Tuple

from emfrp_debugger.emfrp_bridge.core.gdb_interface import GDBInterface
from emfrp_debugger.emfrp_bridge.core.input_interface import InputInterface, InputNode
from emfrp_debugger.emfrp_bridge.services.exec_controller import CallbackResult
from emfrp_debugger.emfrp_bridge.services.mapping.source_mapping import SourceMapping
from returns.result import Result, Failure, Success

MAX_UNLOADED_ITERS = 100000
DST_TRACE_FILE = "trace.txt"

class SavedInputTraceIter(InputInterface):
    def __init__(self):
        self._pos: int = 0
        self._buf: List[List[InputNode]] = []

    def next(self) -> Optional[List[InputNode]]:
        if self._pos >= len(self._buf):
            return None
        rec = self._buf[self._pos]
        self._pos += 1
        return rec

    def deactivate(self) -> None: 
        pass

    def load_saved_trace(self, prog_uniq_id: str) -> Result[None, str]:
        # check if file exists

        if not os.path.exists(DST_TRACE_FILE):
            return Failure(f"Trace file '{DST_TRACE_FILE}' does not exist.")
        try:
            with open(DST_TRACE_FILE, "r") as f:
                lines = f.readlines()
                if len(lines) == 0:
                    return Failure(f"unexpected empty trace file: '{DST_TRACE_FILE}'")
                if lines[0].strip() != prog_uniq_id:
                    return Failure(
                        f"trace file '{DST_TRACE_FILE}' does not match the program "
                        "being debugged."
                    )
                for line in lines[1:]:
                    line = line.strip()
                    if line == "":
                        continue
                    parts = line.split(",")
                    record: List[InputNode] = []
                    for part in parts:
                        nv = part.split("=")
                        if len(nv) != 2:
                            return Failure(
                                f"Malformed trace file '{DST_TRACE_FILE}': "
                                f"invalid record '{part}'"
                            )
                        node_name = nv[0].strip()
                        value = nv[1].strip()
                        record.append(InputNode(node_name=node_name, value=value))
                    self._buf.append(record)
            return Success(None)

        except Exception as e:
            return Failure(f"Failed to open trace file '{DST_TRACE_FILE}': {e}")

class InputTraceManager:
    def __init__(self, input_interface: InputInterface, mapping: SourceMapping):
        self._input_interface = input_interface
        self._next_iter: int = 0

        self._c_exp: List[Tuple[str, str]] = []
        self._buf: List[List[Tuple[str, int]]] = []
        self._err: Optional[str] = None

        for node_name in mapping.input_nodes():
            nd_info = mapping.get_node_info(node_name)
            if nd_info is None:
                raise ValueError(
                    f"InputTraceManager: Unknown input node name: {node_name}"
                )
            self._c_exp.append((node_name, nd_info.c_exp))

    def save_trace(self, prog_uniq_id: str) -> None:
        try:
            with open(DST_TRACE_FILE, "w") as f:
                f.write(f"{prog_uniq_id}\n")
                for rec in self._buf:
                    line_parts: List[str] = []
                    for value, idx in rec:
                        node_name, _ = self._c_exp[idx]
                        line_parts.append(f"{node_name}={value}")
                    line = ",".join(line_parts)
                    f.write(f"{line}\n")
        except Exception as e:
            print(f"InputTraceManager: Failed to save trace to '{DST_TRACE_FILE}': {e}")

    def current_iter(self) -> Optional[int]:
        if self._next_iter == 0:
            return None
        return self._next_iter - 1

if req.kind == "start":
    self.attach(str(req.params.mappingPath))
    assert self._debugger is not None

    if req.params.executionMode == "user-replay":
        res = self._debugger.load_input_interface()
        if isinstance(res, Failure):
            send_response(ResponseCommandFail(
                id=req.id,
                kind="commandFail",
                params=ResponseParamWithMessage(message="No replay data")
            ))
            continue
    elif req.params.executionMode == "user-input":
        if self._input_interface is not None:
            self._debugger.register_input_interface(self._input_interface)
        else:
            send_response(ResponseCommandFail(
                id=req.id,
                kind="commandFail",
                params=ResponseParamWithMessage(message="No Input interface is registered")))
            continue

async startRequest(mappingPath: string | undefined, executionMode: ExecutionMode, stopOnEntry: boolean): Promise<string | EmdbResponseStartParam> {
    const res = await this.call('start', { mappingPath, executionMode, stopOnEntry }, 100000);
    if (res.kind !== 'start') {
        if (res.kind === 'commandFail') {
            const msg = res.params.message;
            return msg;
        }
        engineErr(`start request failed: ${JSON.stringify(res)}`);
    }
    try {
        return {
            nodes: res.params.nodes,
            edges: res.params.edges,
            inputNodes: res.params.inputNodes,
            outputNodes: res.params.outputNodes
        };
    } catch {
        engineErr(`start response parse error: ${JSON.stringify(res)}`);
        return "Internal error in start response";
    }
}

if (!config.executionMode) {
    const pick = await vscode.window.showQuickPick(
        [
            { label: "Normal", description: "通常実行", mode: "normal"},
            { label: "User Input Mode", description: "ユーザーが与える時変値を使って実行", mode: "user-input"},
            { label: "User Replay Mode", description: "最後に与えた時変値を使って実行", mode: "user-replay"}
        ],
        {
            placeHolder: "Emfrpの実行モードを選択してください"
        }
    );
    if (!pick) {
        return undefined;
    }
    config.executionMode = pick.mode;
}
